<script setup lang="ts">
import {ref,watch,computed} from 'vue';
import {ElDrawer} from 'element-plus';
import {Search,Package,RefreshCw,Download,CheckCircle2} from '@lucide/vue';
import type {MethodPackageOverview,MethodPackageEntry} from '../../../../../packages/contracts/src/method-packages.js';
const props=defineProps<{locale:'zh'|'en';active:boolean}>(),emit=defineEmits<{example:[text:string]}>();
const state=ref<MethodPackageOverview|null>(null),query=ref(''),busy=ref(false),error=ref(''),selected=ref<MethodPackageEntry|null>(null);
const reviewer=ref(''),reason=ref(''),reviewOpen=ref(false);
const t=(zh:string,en:string)=>props.locale==='zh'?zh:en;
const rows=computed(()=>state.value?.entries.filter(e=>[e.pin.id,...Object.values(e.manifest.name),...Object.values(e.manifest.description)].join(' ').toLowerCase().includes(query.value.toLowerCase()))??[]);
const status=(e:MethodPackageEntry)=>e.status==='withdrawn'?t('已撤回','Withdrawn'):e.status==='reference-reproduced'?t('参考复现通过','Reference reproduced'):e.executable?t('待参考复现','Reference pending'):t('候选 · 暂不可运行','Candidate · unavailable');
const blockers:Record<string,[string,string]>={METHOD_LOCAL_REVIEW_REQUIRED:['尚未本机审核','Local review required'],METHOD_SIGNED_PUBLICATION_REQUIRED:['尚未签名发布','Signed publication required'],METHOD_ADAPTER_UNAVAILABLE_OR_PINS_CHANGED:['未接入执行工具或版本不匹配','Adapter unavailable or version mismatch'],METHOD_LICENSE_REVIEW_REQUIRED:['许可待审核','License review required'],METHOD_WITHDRAWN:['此版本已撤回','Version withdrawn'],METHOD_SOURCE_CHANGED:['源文件已变化','Source changed'],METHOD_ENVIRONMENT_LOCK_CHANGED:['依赖锁已变化','Dependency lock changed'],METHOD_EXECUTABLE_CHANGED:['运行代码已变化','Executable changed'],METHOD_REFERENCE_CHANGED:['参考数据已变化','Reference changed'],METHOD_TRUST_HISTORY_INVALID:['发布历史未通过检查','Invalid publication history']};
function blocker(code:string){return blockers[code]?.[props.locale==='zh'?0:1]??code;}
async function load(){state.value=await window.materialsx.getMethodPackages();if(selected.value)selected.value=state.value.entries.find(e=>e.pin.sha256===selected.value!.pin.sha256)??null;}
async function perform(fn:()=>Promise<unknown>){busy.value=true;error.value='';try{await fn();await load();}catch(e){error.value=String(e);}finally{busy.value=false;}}
const importPackage=()=>perform(()=>window.materialsx.importMethodPackage());
const verifyPackage=()=>selected.value&&perform(()=>window.materialsx.verifyMethodPackage({...selected.value!.pin}));
watch(()=>props.active,v=>{if(v)void perform(load);},{immediate:true});
function open(e:MethodPackageEntry){selected.value=e;reviewOpen.value=false;reason.value='';}
async function review(decision:'approve'|'reject'){if(!selected.value)return;await perform(()=>window.materialsx.reviewMethodPackage({pin:{...selected.value!.pin},reviewer:reviewer.value.trim(),reason:reason.value.trim(),decision}));reviewOpen.value=false;}
function example(text:string){selected.value=null;emit('example',text);}
</script>
<template>
<section class="method-packages" data-testid="method-packages-panel">
  <div class="package-heading"><div><h2>{{t('方法包','Method packages')}}</h2><p>{{t('查看方法的适用范围、来源、版本和参考复现记录。','Inspect scope, sources, versions and reference reproduction records.')}}</p></div>
    <div class="actions"><button class="secondary-button" :disabled="busy" @click="perform(load)"><RefreshCw :size="15"/>{{t('刷新','Refresh')}}</button><button class="secondary-button" :disabled="busy" @click="importPackage"><Download :size="15"/>{{t('导入方法包或发布文件','Import package or release')}}</button></div></div>
  <p v-if="error||state?.error" role="alert" class="package-error">{{error||state?.error}}</p>
  <div class="package-toolbar"><label class="package-search"><Search :size="17"/><input v-model="query" :placeholder="t('搜索方法名称…','Search methods…')"/></label><span class="muted">{{rows.length}} {{t('个版本','versions')}} · {{t('发布序号','Release')}} {{state?.sequence??0}}</span></div>
  <div class="package-grid"><button v-for="entry in rows" :key="entry.pin.sha256" class="package-card" @click="open(entry)"><div class="package-card-top"><Package :size="22"/><span class="package-status" :class="entry.status">{{status(entry)}}</span></div><h3>{{entry.manifest.name[locale]}}</h3><p>{{entry.manifest.description[locale]}}</p><footer><span>{{entry.pin.version}} · {{entry.origin==='bundled'?t('内置','Built in'):t('社区','Community')}}</span><span>{{t('查看详情','View details')}} →</span></footer></button></div>
  <p v-if="!rows.length&&!busy" class="empty-list">{{t('没有匹配的方法包','No matching packages')}}</p>
  <p class="package-note">{{t('参考复现只检验指定案例。材料适用性和科研结论仍需验证；导入说明不会安装或执行外部代码。','Reference reproduction checks specified cases only. Material applicability and scientific conclusions require validation. Imported metadata does not install or execute external code.')}}</p>
  <details v-if="state?.releases.length" class="package-history"><summary>{{t('发布与撤回历史','Publication & withdrawal history')}}</summary><div v-for="r in state.releases" :key="r.payloadSha256"><strong>#{{r.payload.sequence}} · {{r.payload.action}}</strong> · {{r.payload.issuedAt}}<p>{{r.keyId}} · {{r.payload.entries.length}} {{t('个方法','methods')}} · {{r.payload.withdrawals.length}} {{t('个撤回版本','withdrawn versions')}}</p></div></details>
  <ElDrawer :model-value="!!selected" class="method-package-drawer" :title="selected?.manifest.name[locale]??''" size="min(780px, 96vw)" @close="selected=null">
    <div v-if="selected" class="package-details" data-testid="method-package-details">
      <div class="detail-status"><span class="package-status" :class="selected.status">{{status(selected)}}</span><span>{{selected.pin.version}}</span><span>{{t('材料领域验证：尚未完成','Material-domain validation: pending')}}</span></div>
      <p>{{selected.manifest.description[locale]}}</p><p v-if="error" class="package-error" role="alert">{{error}}</p>
      <div v-if="selected.blockers.length" class="package-note"><p v-for="b in selected.blockers" :key="b">{{blocker(b)}}</p></div>
      <section><h3>{{t('适用范围','Scope')}}</h3><p v-for="s in selected.manifest.scope" :key="s.en">{{s[locale]}}</p><p v-for="s in selected.manifest.limitations" :key="s.en" class="muted">{{s[locale]}}</p></section>
      <section><h3>{{t('使用示例','Examples')}}</h3><article v-for="s in selected.manifest.skill.examples" :key="s.en" class="package-example"><p>{{s[locale]}}</p><button class="secondary-button" @click="example(s[locale])">{{t('填入对话','Use in chat')}}</button></article></section>
      <section><div class="package-heading"><h3>{{t('参考复现','Reference reproduction')}}</h3><button class="primary-button" data-testid="package-verify" :disabled="busy||!selected.executable" @click="verifyPackage"><CheckCircle2 :size="15"/>{{busy?t('处理中…','Running…'):t('运行参考案例','Run reference case')}}</button></div><p>{{selected.manifest.reference.scope[locale]}}</p><p><a :href="selected.manifest.reference.source" target="_blank" rel="noreferrer">{{selected.manifest.reference.file}}</a> · {{t('绝对 / 相对容差','Absolute / relative tolerance')}} {{selected.manifest.reference.absoluteTolerance}} / {{selected.manifest.reference.relativeTolerance}}</p>
        <div v-if="selected.reference" class="package-reference"><p>{{selected.reference.at}} · {{selected.reference.environment.node}} / {{selected.reference.environment.platform}} / {{selected.reference.environment.arch}}</p><div class="package-table-scroll"><table><thead><tr><th>{{t('字段','Field')}}</th><th>{{t('实算值','Computed')}}</th><th>{{t('参考值','Reference')}}</th><th>{{t('误差','Error')}}</th><th>{{t('结果','Result')}}</th></tr></thead><tbody><tr v-for="c in selected.reference.checks" :key="c.field"><td>{{c.field}}</td><td>{{c.actual.toPrecision(12)}}</td><td>{{c.expected.toPrecision(12)}}</td><td>{{c.error.toExponential(2)}}</td><td>{{c.passed?t('通过','Pass'):t('失败','Fail')}}</td></tr></tbody></table></div></div>
      </section>
      <section><h3>{{t('来源与许可','Sources & licenses')}}</h3><article v-for="s in selected.manifest.sources" :key="s.url" class="package-source"><a :href="s.url" target="_blank" rel="noreferrer">{{s.citation}}</a><p class="mono muted">{{s.revision}}</p></article><dl><template v-for="l in selected.manifest.licenses" :key="l.component"><dt>{{l.component}} · {{l.status}}</dt><dd>{{l.identifier}}<p class="muted">{{l.basis}}</p><a v-if="l.url" :href="l.url" target="_blank" rel="noreferrer">{{t('许可来源','License source')}}</a></dd></template></dl></section>
      <section><h3>{{t('运行要求与版本','Runtime & version')}}</h3><p>{{selected.manifest.execution.tool}} · {{selected.manifest.execution.backend}} · {{selected.manifest.execution.gpu?'GPU':'CPU'}} / Float64 · {{selected.manifest.execution.memoryMiB}} MiB · ≤ {{selected.manifest.execution.maxSamples}} {{t('条观测','observations')}}</p><p class="mono">{{selected.pin.id}} / {{selected.pin.version}}<br/>SHA256 {{selected.pin.sha256}}</p><details><summary>{{t('代码、依赖与数据合同','Code, dependencies & data contracts')}}</summary><p class="mono">{{selected.manifest.execution.files}}</p><p class="mono">{{selected.manifest.execution.dependencyLock}}</p><p class="mono">{{selected.manifest.execution.inputSchema}}<br/>{{selected.manifest.execution.outputSchema}}</p></details></section>
      <section v-if="selected.origin==='community'"><button class="secondary-button" @click="reviewOpen=!reviewOpen">{{t('本机审核','Local review')}}</button><form v-if="reviewOpen" class="package-review" @submit.prevent="review('approve')"><label>{{t('审核人','Reviewer')}}<input v-model="reviewer" required maxlength="200"/></label><label>{{t('审核依据','Review basis')}}<textarea v-model="reason" required maxlength="2000"/></label><p class="muted">{{t('本机审核不替代签名发布、适配器或真实参考复现。','Local review does not replace signed publication, an adapter or actual reference reproduction.')}}</p><div class="actions"><button class="primary-button" :disabled="busy||!reviewer.trim()||!reason.trim()">{{t('记录审核通过','Record approval')}}</button><button type="button" class="secondary-button" :disabled="busy||!reviewer.trim()||!reason.trim()" @click="review('reject')">{{t('记录拒绝','Record rejection')}}</button></div></form></section>
    </div>
  </ElDrawer>
</section>
</template>
<style scoped>
.method-packages{min-width:0;display:grid;gap:20px;color:var(--text)}.package-heading{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}.package-heading h2,.package-heading h3{margin:0}.package-heading p{margin:8px 0 0;color:var(--muted)}.package-toolbar{display:flex;align-items:center;gap:16px;flex-wrap:wrap}.package-search{display:flex;align-items:center;gap:10px;background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:10px 14px;flex:1;max-width:460px}.package-search input{border:0;outline:0;min-width:0;width:100%;color:var(--text);background:transparent}.package-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,310px),1fr));gap:16px}.package-card{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:20px;cursor:pointer;text-align:left;color:var(--text);min-width:0}.package-card:hover{border-color:var(--accent)}.package-card-top,.package-card footer{display:flex;align-items:center;justify-content:space-between;gap:10px}.package-card h3{margin:18px 0 10px;font-size:17px}.package-card p{color:var(--muted);line-height:1.7;margin:0 0 22px}.package-card footer{font-size:12px;color:var(--muted)}.package-status{font-size:12px;border:1px solid var(--line);border-radius:20px;padding:5px 10px;white-space:normal}.package-status.reference-reproduced{color:var(--accent)}.package-note{padding:14px 16px;border-radius:12px;background:var(--panel);border:1px solid var(--line);color:var(--muted);font-size:13px;line-height:1.7;margin:0}.package-note p{margin:4px 0}.package-error{color:var(--danger,#c44);overflow-wrap:anywhere}.muted{color:var(--muted)}.package-history>div{padding:14px 0;border-bottom:1px solid var(--line)}.package-details{min-width:0;display:grid;gap:24px;line-height:1.7}.package-details section{min-width:0;border-top:1px solid var(--line);padding-top:20px}.package-details h3{font-size:16px;margin:0 0 12px}.package-details p{margin:8px 0;overflow-wrap:anywhere}.detail-status{display:flex;gap:12px;flex-wrap:wrap;font-size:12px;color:var(--muted)}.package-example{padding:16px;background:var(--panel-subtle,var(--panel));border:1px solid var(--line);border-radius:12px}.package-example p{margin:0 0 12px;white-space:pre-wrap}.package-table-scroll{overflow:auto;max-width:100%}table{border-collapse:collapse;font-size:12px;width:100%;white-space:nowrap}td,th{padding:10px 12px;border-bottom:1px solid var(--line);text-align:left}a{color:var(--accent);overflow-wrap:anywhere}.mono{font-family:monospace;font-size:12px;overflow-wrap:anywhere;white-space:normal}.package-source{padding:8px 0}dl{display:grid;grid-template-columns:100px minmax(0,1fr);gap:12px;font-size:13px}dd{margin:0}.package-review{display:grid;gap:14px;margin-top:16px}.package-review label{display:grid;gap:6px}.package-review input,.package-review textarea{padding:10px;border:1px solid var(--line);border-radius:8px;color:var(--text);background:var(--panel);width:100%;box-sizing:border-box}.package-review textarea{min-height:90px;resize:vertical}
:global(.method-package-drawer.el-drawer){background:var(--panel);color:var(--text)}:global(.method-package-drawer .el-drawer__header){color:var(--text);border-bottom:1px solid var(--line);padding-bottom:18px;margin-bottom:0}:global(.method-package-drawer .el-drawer__body){overflow:auto;min-width:0;padding:24px}
@media(max-width:760px){.package-card{padding:16px}.package-details{gap:18px}dl{grid-template-columns:1fr}dd{margin-bottom:10px}}
</style>
